from flask import Flask, render_template, request, jsonify
import subprocess
import os

app = Flask(__name__)

@app.route('/')
def index():
    return render_template('index.html')

@app.route('/api/ai-bridge', methods=['POST'])
def ai_bridge():
    data = request.json
    user_prompt = data.get('prompt', '')

    pipeline_log = []
    pipeline_log.append(f"👴 [ปู่ใหญ่ Orchestrator]: รับโจทย์จากป๋า -> '{user_prompt}' กำลังกระจายงานให้ทีม...")
    pipeline_log.append(f"👨‍พ่อ [Gemini Agent]: วิเคราะห์โครงสร้างและต้นตอของปัญหาสำเร็จ")
    pipeline_log.append(f"👩‍แม่ [OpenAI Agent]: ตรวจสอบตรรกะคำสั่งและแนวทางแก้ไข")
    pipeline_log.append(f"🧔 ลุง [Claude Agent] & 💻 พี่ใหญ่ [Copilot]: ตรวจสอบความถูกต้องของชุดโค้ด")
    pipeline_log.append(f"👦 พี่ชาย [Llama Agent] & 🤖 น้องเล็ก [Custom Bot]: สรุปผลลัพธ์พร้อมใช้งาน")

    final_output = "\n".join(pipeline_log) + "\n\n✨ [AI ครอบครัวรุมวิเคราะห์]: ประมวลผลตรรกะเสร็จสิ้นเรียบร้อย"

    # ระบบท่อเสียงแจ้งเตือนอัตโนมัติ (ถนอมสายตาแอดมิน)
    try:
        subprocess.run("play -n synth 0.15 sin 880 2>/dev/null", shell=True)
        speech_text = "กองทัพ AI ประมวลผลโจทย์เสร็จเรียบร้อยแล้วครับป๋า"
        subprocess.run(f"termux-tts-speak '{speech_text}'", shell=True)
    except Exception as e:
        print("Audio alert error:", e)

    return jsonify({
        "status": "success", 
        "bridge_response": final_output
    })

@app.route('/api/ai-control', methods=['POST'])
def ai_control():
    data = request.json
    prompt = data.get('prompt', '')
    return jsonify({"status": "success", "response": f"AI Engine processed: {prompt}"})

@app.route('/api/workspace', methods=['POST'])
def workspace_agent():
    data = request.json
    command = data.get('command', '')
    return jsonify({"status": "success", "response": f"Workspace executed: {command}"})

@app.route('/api/shell', methods=['POST'])
def termux_shell():
    data = request.json
    cmd = data.get('cmd', '')
    try:
        res = subprocess.check_output(cmd, shell=True, stderr=subprocess.STDOUT, text=True, timeout=5)
    except Exception as e:
        res = str(e)
    return jsonify({"status": "success", "output": res})

@app.route('/api/home-files', methods=['GET'])
def home_files():
    home_dir = os.path.expanduser('~')
    try:
        files = os.listdir(home_dir)
    except Exception as e:
        files = [str(e)]
    return jsonify({"status": "success", "path": home_dir, "files": files[:15]})

@app.route('/api/external-storage', methods=['GET'])
def external_storage():
    ext_path = '/storage/emulated/0/Dev/ai_girl_bot'
    try:
        files = os.listdir(ext_path)
    except Exception as e:
        files = [str(e)]
    return jsonify({"status": "success", "path": ext_path, "files": files})

if __name__ == '__main__':
    app.run(host='0.0.0.0', port=9505, debug=False)

