from flask import Flask, request, jsonify
import socket

app = Flask(__name__)

HTML_CONTENT = """<!DOCTYPE html>
<html lang="th">
<head>
    <meta charset="UTF-8">
    <meta name="viewport" content="width=device-width, initial-scale=1.0, maximum-scale=1.0, user-scalable=no">
    <title>VAULT FULL CONTROL</title>
    <style>
        * { box-sizing: border-box; margin: 0; padding: 0; }
        body { background-color: #121212; color: #e0e0e0; font-family: monospace, sans-serif; padding: 8px; zoom: 0.82; }
        .container { max-width: 100%; margin: 0 auto; }
        .card { background: #1e1e1e; border: 1px solid #333; border-radius: 6px; padding: 10px; margin-bottom: 8px; }
        .card h3 { font-size: 13px; margin-bottom: 6px; color: #4CAF50; }
        input[type="text"] { width: 100%; background: #2d2d2d; border: 1px solid #444; color: #fff; padding: 6px; border-radius: 4px; margin-bottom: 6px; font-family: monospace; font-size: 12px; }
        button { background: #4CAF50; color: white; border: none; padding: 6px 10px; border-radius: 4px; cursor: pointer; font-weight: bold; font-size: 12px; }
        .output { background: #111; border: 1px solid #333; padding: 6px; border-radius: 4px; font-size: 11px; color: #a5d6a7; margin-top: 4px; word-break: break-all; white-space: pre-wrap; }
    </style>
</head>
<body>
    <div class="container">
        <div class="card">
            <h3>🤖 1. AI-to-AI Bridge:</h3>
            <input type="text" id="bridge-input" placeholder="ป้อนคำสั่ง...">
            <button onclick="sendApi('bridge-input', '/api/ai-bridge', 'bridge-output')">ส่งข้ามสะพาน AI</button>
            <div class="output" id="bridge-output">รอรับคำสั่ง...</div>
        </div>
        <div class="card">
            <h3>💬 2. Direct AI Control:</h3>
            <input type="text" id="chat-input" placeholder="คุย/สั่งการ AI...">
            <button onclick="sendApi('chat-input', '/api/ai', 'chat-output')">ส่งคำสั่ง AI</button>
            <div class="output" id="chat-output">รอรับคำสั่ง...</div>
        </div>
    </div>

    <script>
        async function sendApi(inputId, url, outputId) {
            const inputVal = document.getElementById(inputId).value;
            const outputBox = document.getElementById(outputId);
            outputBox.innerText = '⏳ กำลังส่งข้อมูลไปยัง AI...';

            try {
                const response = await fetch(url, {
                    method: 'POST',
                    headers: {'Content-Type': 'application/json'},
                    body: JSON.stringify({ prompt: inputVal })
                });
                const data = await response.json();
                outputBox.innerText = data.output || data.bridge_response || JSON.stringify(data);
            } catch (err) {
                outputBox.innerText = '❌ เกิดข้อผิดพลาด: ' + err;
            }
        }
    </script>
</body>
</html>"""

@app.route('/')
def index():
    return HTML_CONTENT

@app.route('/api/ai', methods=['POST'])
def api_ai():
    data = request.get_json() or {}
    prompt = data.get('prompt', '')
    print(f"\n[Termux Log] รับคำสั่ง AI: {prompt}")
    return jsonify({"output": f"🤖 AI รับทราบคำสั่งป๋าแล้วครับ: {prompt}\n(จำลองการทำงานเรียบร้อย)"})

@app.route('/api/ai-bridge', methods=['POST'])
def api_ai_bridge():
    data = request.get_json() or {}
    prompt = data.get('prompt', '')
    print(f"\n[Termux Log] สะพาน AI ส่งต่อข้อมูล: {prompt}")
    return jsonify({"bridge_response": f"⚡ ข้อมูลถูกส่งข้ามสะพาน AI สำเร็จ!\nเนื้อหา: {prompt}"})

def find_port(start=9510):
    for p in range(start, 9999):
        with socket.socket(socket.AF_INET, socket.SOCK_STREAM) as s:
            try:
                s.bind(('127.0.0.1', p))
                return p
            except OSError:
                continue
    return start

if __name__ == '__main__':
    port = find_port(9510)
    print(f"🚀 เซิร์ฟเวอร์พร้อมลุยที่ http://localhost:{port}")
    app.run(host='0.0.0.0', port=port, debug=False)
